#!/usr/bin/env bash
# GATE AUTHORSHIP -- every unmarked file under a manufactured root is an
# ADMITTED, COUNTED exception, or the tree is refused.
#
# VISION-2030 section 24 names "ggen-only manufacture requires routine
# privileged handwritten source commits" as a falsifier of the whole thesis,
# and section 2 requires any direct source intervention to be "visible,
# bounded, and counted as manufacturing debt". Until this gate existed the
# repo could not tell: gate_m2_check.sh only ever looks for files that
# CARRY the "GENERATED by ggen" marker, so an unmarked file sitting in src/
# or test/ was invisible to every gate -- 33 of them at admission time
# (12 native-engine facades, 14 hand-authored ExUnit qualification files,
# src/beam4pm.app.src, 6 hand-authored docs/reference/*.md), with zero
# admission records anywhere (git log --grep=privileged: 0; receipts/: 0).
#
# This gate turns that prose into a mechanical check. The admitted set is
# NOT a shell array in this file (that would just be a second hand-
# maintained HAND_AUTHORED_DEPENDENT_TESTS list): it is read from the
# MANUFACTURED manifest schema/beam4pm_hand_authored_source.tsv, which
# ggen renders from the consumer ontology's bpm:HandAuthoredSource
# individuals (one per admitted file; vocabulary in
# vendor/ggen-marketplace/packs/beam4pm-process-model-pack/ontology.ttl,
# template templates/beam4pm_hand_authored_source.tsv.tmpl). The manifest
# must itself carry the GENERATED marker, so a hand-written one is refused.
#
# Checks (default mode), every one a refusal with a typed REFUSED_* line:
#   REFUSED_UNADMITTED        unmarked file under a root with no admission
#   REFUSED_STALE_ADMISSION   admitted path neither on disk nor in the git index
#                             (tracked-but-absent is TRANSIENT_ABSENT: the
#                             gate_m2 regeneration window, not a finding)
#   REFUSED_CONTRADICTION     admitted path now carries the GENERATED marker
#   REFUSED_SHA_DRIFT         admitted debt file's bytes changed since admission
#   REFUSED_EXPIRED           admission date has passed (renew visibly or delete)
#   REFUSED_MISSCOPED         admitted path is not under any manufactured root
#   REFUSED_UNBOUND_DEBT      debt row without a sha256 or expiry (standing grant)
#   REFUSED_MANIFEST_*        manifest missing, unmanufactured, or malformed
#
# --exercise additionally runs every distinct acceptance command from the
# manifest (from the repo root) and refuses a failing command
# (REFUSED_ACCEPTANCE_FAILED) or a vacuous one -- an ExUnit run where every
# test was skipped, or zero tests ran (REFUSED_VACUOUS_ACCEPTANCE) -- unless
# the row names a prerequisite artifact that is absent on this host, which is
# reported as ACCEPTANCE_BLOCKED_PREREQUISITE (honest BLOCKED, not a pass).
#
# File universe: `git ls-files --cached --others --exclude-standard` under
# the roots, never a raw `find` -- so infra/gcp/cloudrun/.terraform/ (a
# real gitignored provider cache on the dev host) and anything else
# gitignored is out of scope by construction, while a brand-new untracked
# hand-authored file IS in scope. A tracked path deleted from disk is
# skipped (gate_m2_check.sh's delete->regenerate window runs `mix test`,
# and therefore this gate, with marked files transiently absent).
#
# Marker predicate is gate_m2_check.sh's exact one: first 3 lines,
# case-insensitive -- docs/reference/beam4pm_types_reference.md reads
# "*Generated by ggen ...*", and three unmarked files mention the marker
# text in body prose, so neither an exact-case nor a whole-file grep would
# classify correctly.
#
# Portable to bash 3.2 on purpose (no mapfile, no associative arrays):
# the manufactured Chicago test test/beam4pm_authorship_gate_test.exs runs
# this script through System.cmd("bash", ...) on whatever bash PATH holds.
set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "$0")" && pwd)"
ROOT="$(cd "$SCRIPT_DIR/.." && pwd)"
MANIFEST=""
MODE="check"
MARKER="GENERATED by ggen"
ROOTS="src lib gleam/src gleam/test test schema docs/reference infra/gcp/cloudrun infra/gcp/packer"
TODAY="${GATE_AUTHORSHIP_TODAY:-$(date -u +%Y-%m-%d)}"

usage() {
  cat <<EOF
usage: bash scripts/gate_authorship_check.sh [--root DIR] [--manifest FILE] [--exercise]
  --root DIR       git working tree to check (default: this repo)
  --manifest FILE  admission manifest (default: <root>/schema/beam4pm_hand_authored_source.tsv)
  --exercise       also run every admitted acceptance command and refuse failing/vacuous ones
EOF
}

while [ $# -gt 0 ]; do
  case "$1" in
    --root) ROOT="$(cd "$2" && pwd)"; shift 2 ;;
    --manifest) MANIFEST="$2"; shift 2 ;;
    --exercise) MODE="exercise"; shift ;;
    -h|--help) usage; exit 0 ;;
    *) echo "gate_authorship_check.sh: unknown argument: $1" >&2; usage >&2; exit 2 ;;
  esac
done

if [ -z "$MANIFEST" ]; then
  MANIFEST="$ROOT/schema/beam4pm_hand_authored_source.tsv"
else
  case "$MANIFEST" in
    /*) ;;
    *) MANIFEST="$(pwd)/$MANIFEST" ;;
  esac
fi

cd "$ROOT"

WORK="$(mktemp -d)"
trap 'rm -rf "$WORK"' EXIT
FINDINGS="$WORK/findings"
ADMITTED_PATHS="$WORK/admitted_paths"
ROWS="$WORK/rows"
: > "$FINDINGS"
: > "$ADMITTED_PATHS"
: > "$ROWS"

refuse() {
  # $1 = typed code, $2 = subject, $3 = optional detail
  if [ -n "${3:-}" ]; then
    echo "$1: $2 ($3)" >> "$FINDINGS"
  else
    echo "$1: $2" >> "$FINDINGS"
  fi
}

is_marked() {
  head -3 "$1" 2>/dev/null | grep -qi "$MARKER"
}

in_scope() {
  local p="$1" r
  for r in $ROOTS; do
    case "$p" in
      "$r"/*) return 0 ;;
    esac
  done
  return 1
}

prerequisite_present() {
  # A prerequisite is either a path (repo-root-relative or absolute) that
  # must exist, or "cmd:<shell command>" whose zero exit means the external
  # collaborator is reachable (e.g. cmd:kubectl --context kind-ex4pm
  # cluster-info for the k8s qualification files -- the same probe those
  # tests use for their own @moduletag skip decision).
  case "$1" in
    cmd:*) bash -c "${1#cmd:}" >/dev/null 2>&1 ;;
    *) [ -e "$1" ] ;;
  esac
}

echo "== GATE AUTHORSHIP: unmarked files under manufactured roots must be admitted =="
echo "root: $ROOT"
echo "manifest: $MANIFEST"

if ! git rev-parse --is-inside-work-tree >/dev/null 2>&1; then
  echo "REFUSED_NOT_A_GIT_TREE: $ROOT"
  echo "GATE AUTHORSHIP: FAIL -- file universe is git ls-files; $ROOT is not a git working tree" >&2
  exit 1
fi

if [ ! -f "$MANIFEST" ]; then
  echo "REFUSED_MANIFEST_MISSING: $MANIFEST (regenerate: rm -f ggen.lock && ggen sync run)"
  echo "GATE AUTHORSHIP: FAIL -- admission manifest missing" >&2
  exit 1
fi
if ! is_marked "$MANIFEST"; then
  echo "REFUSED_MANIFEST_UNMANUFACTURED: $MANIFEST (no '$MARKER' marker in its first 3 lines -- the admitted set must come from ggen, never a hand-maintained list)"
  echo "GATE AUTHORSHIP: FAIL -- admission manifest is not manufactured output" >&2
  exit 1
fi

# --- pass 1: parse the manufactured manifest ------------------------------
# Columns: path kind counts_as_debt sha256 expires acceptance_command prerequisite
grep -v '^#' "$MANIFEST" | grep -v '^[[:space:]]*$' > "$ROWS" || true
malformed=0
while IFS=$'\t' read -r path kind debt sha expires cmd prereq extra; do
  if [ -z "$path" ] || [ -z "$kind" ] || [ -z "$debt" ] || [ -z "$sha" ] || [ -z "$expires" ] || [ -z "$cmd" ] || [ -z "$prereq" ] || [ -n "${extra:-}" ]; then
    refuse REFUSED_MANIFEST_MALFORMED "$path" "expected exactly 7 tab-separated columns"
    malformed=1
    continue
  fi
  case "$debt" in true|false) ;; *) refuse REFUSED_MANIFEST_MALFORMED "$path" "counts_as_debt must be true or false, got '$debt'"; malformed=1 ;; esac
  if [ "$expires" != "-" ] && ! echo "$expires" | grep -Eq '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'; then
    refuse REFUSED_MANIFEST_MALFORMED "$path" "expires must be YYYY-MM-DD or -, got '$expires'"
    malformed=1
  fi
  if [ "$sha" != "-" ] && ! echo "$sha" | grep -Eq '^[0-9a-f]{64}$'; then
    refuse REFUSED_MANIFEST_MALFORMED "$path" "sha256 must be 64 lowercase hex chars or -, got '$sha'"
    malformed=1
  fi
  echo "$path" >> "$ADMITTED_PATHS"
done < "$ROWS"

admitted_n=$(wc -l < "$ADMITTED_PATHS" | tr -d ' ')
debt_n=$(awk -F'\t' '$3 == "true"' "$ROWS" | wc -l | tr -d ' ')
if [ "$admitted_n" -ne "$(sort -u "$ADMITTED_PATHS" | wc -l | tr -d ' ')" ]; then
  sort "$ADMITTED_PATHS" | uniq -d | while read -r dup; do
    refuse REFUSED_MANIFEST_MALFORMED "$dup" "admitted more than once"
  done
fi
echo "admitted: $admitted_n ($debt_n counted as manufacturing debt)"

# --- pass 2: every admitted path must be real, unmarked, in scope, unchanged, unexpired
while IFS=$'\t' read -r path kind debt sha expires cmd prereq extra; do
  [ -n "$path" ] || continue
  if ! in_scope "$path"; then
    refuse REFUSED_MISSCOPED "$path" "not under any manufactured root: $ROOTS"
    continue
  fi
  if [ ! -f "$path" ]; then
    # Tracked in the git index but absent from disk is the regeneration
    # window, not a stale admission: gate_m2_check.sh stashes its
    # HAND_AUTHORED_DEPENDENT_TESTS out of test/ while the igniter leg runs
    # `mix test` (and therefore this gate) mid-pass-3. A clean checkout
    # (CI) has index == disk, so a genuinely deleted-and-committed admission
    # is still refused there; an uncommitted `rm` is refused the moment it
    # is staged. Same rule pass 3 applies to marked files.
    if git ls-files --error-unmatch -- "$path" >/dev/null 2>&1; then
      echo "TRANSIENT_ABSENT: $path (tracked in the index, not on disk -- regeneration window, not a finding)"
      continue
    fi
    refuse REFUSED_STALE_ADMISSION "$path" "admitted but neither on disk nor in the git index -- delete its bpm:HandAuthoredSource individual from ontology.ttl and regenerate"
    continue
  fi
  if is_marked "$path"; then
    refuse REFUSED_CONTRADICTION "$path" "admitted as hand-authored but its first 3 lines carry '$MARKER'"
    continue
  fi
  if [ "$debt" = "true" ]; then
    if [ "$sha" = "-" ] || [ "$expires" = "-" ]; then
      refuse REFUSED_UNBOUND_DEBT "$path" "a debt admission must carry a content sha256 and an expiry; a path-only admission is a standing grant"
      continue
    fi
  fi
  if [ "$sha" != "-" ]; then
    actual="$(shasum -a 256 "$path" | awk '{print $1}')"
    if [ "$actual" != "$sha" ]; then
      refuse REFUSED_SHA_DRIFT "$path" "admitted sha256 $sha, on disk $actual -- an edit to admitted hand-authored source is new debt: re-admit it with the new digest in ontology.ttl"
      continue
    fi
  fi
  if [ "$expires" != "-" ] && [ "$expires" \< "$TODAY" ]; then
    refuse REFUSED_EXPIRED "$path" "admission expired $expires (today $TODAY) -- eliminate the debt or renew the admission visibly in ontology.ttl"
    continue
  fi
done < "$ROWS"

# --- pass 3: every unmarked file under a root must be admitted -------------
existing_roots=""
for r in $ROOTS; do
  [ -e "$r" ] && existing_roots="$existing_roots $r"
done
UNIVERSE="$WORK/universe"
: > "$UNIVERSE"
if [ -n "$existing_roots" ]; then
  # shellcheck disable=SC2086
  git ls-files --cached --others --exclude-standard -- $existing_roots | sort -u > "$UNIVERSE"
fi
marked_n=0
unmarked_n=0
while IFS= read -r f; do
  [ -n "$f" ] || continue
  [ -f "$f" ] || continue   # tracked but transiently absent (regeneration window)
  if is_marked "$f"; then
    marked_n=$((marked_n + 1))
    continue
  fi
  unmarked_n=$((unmarked_n + 1))
  if ! grep -qxF -- "$f" "$ADMITTED_PATHS"; then
    refuse REFUSED_UNADMITTED "$f" "no GENERATED marker and no bpm:HandAuthoredSource admission -- either regenerate it from ontology.ttl + a pack template, or admit it (path, kind, principal, reason, acceptance command, sha256, expiry, sunset plan) and regenerate the manifest"
  fi
done < "$UNIVERSE"
echo "universe: $((marked_n + unmarked_n)) files under roots ($marked_n manufactured, $unmarked_n unmarked)"

# --- pass 4 (--exercise): run every admitted acceptance command -----------
blocked_n=0
alive_n=0
if [ "$MODE" = "exercise" ]; then
  echo "== exercising admitted acceptance commands =="
  cut -f6 "$ROWS" | sort -u | while IFS= read -r cmd; do
    [ -n "$cmd" ] || continue
    log="$WORK/acceptance.log"
    set +e
    bash -c "$cmd" > "$log" 2>&1
    status=$?
    set -e
    summary="$(grep -E '^[0-9]+ tests?, [0-9]+ failures?' "$log" | tail -1 || true)"
    if [ "$status" -ne 0 ]; then
      refuse REFUSED_ACCEPTANCE_FAILED "$cmd" "exit $status; ${summary:-no ExUnit summary}"
      tail -20 "$log" | sed 's/^/    | /'
      continue
    fi
    if [ -n "$summary" ]; then
      tests=$(echo "$summary" | sed -E 's/^([0-9]+) tests?, .*/\1/')
      skipped=$(echo "$summary" | sed -nE 's/.*, ([0-9]+) skipped.*/\1/p')
      skipped=${skipped:-0}
      if [ "$tests" -eq 0 ] || [ "$skipped" -eq "$tests" ]; then
        # Vacuous run: every test skipped. Honest only if a declared
        # prerequisite artifact is genuinely absent on this host.
        missing_prereq=""
        while IFS=$'\t' read -r p2 k2 d2 s2 e2 c2 pr2 x2; do
          [ "$c2" = "$cmd" ] || continue
          [ "$pr2" != "-" ] || continue
          if ! prerequisite_present "$pr2"; then
            missing_prereq="$pr2"
          fi
        done < "$ROWS"
        if [ -n "$missing_prereq" ]; then
          echo "ACCEPTANCE_BLOCKED_PREREQUISITE: $cmd ($summary; prerequisite absent: $missing_prereq)"
          echo "blocked" >> "$WORK/blocked"
        else
          refuse REFUSED_VACUOUS_ACCEPTANCE "$cmd" "$summary -- every test skipped and no absent prerequisite declared; a named acceptance nothing runs is RDF prose"
        fi
        continue
      fi
      echo "ACCEPTANCE_ALIVE: $cmd ($summary)"
    else
      echo "ACCEPTANCE_ALIVE: $cmd (exit 0)"
    fi
    echo "alive" >> "$WORK/alive"
  done
  [ -f "$WORK/blocked" ] && blocked_n=$(wc -l < "$WORK/blocked" | tr -d ' ')
  [ -f "$WORK/alive" ] && alive_n=$(wc -l < "$WORK/alive" | tr -d ' ')
fi

findings_n=$(wc -l < "$FINDINGS" | tr -d ' ')
if [ "$findings_n" -gt 0 ]; then
  echo "REFUSED: $findings_n finding(s):"
  sort -u "$FINDINGS" | sed 's/^/  /'
  echo "GATE AUTHORSHIP: FAIL -- $findings_n finding(s)" >&2
  exit 1
fi

if [ "$MODE" = "exercise" ]; then
  echo "GATE AUTHORSHIP: PASS -- $admitted_n admitted ($debt_n counted as manufacturing debt), $unmarked_n unmarked files under roots, 0 findings; acceptance: $alive_n alive, $blocked_n blocked on absent prerequisites"
else
  echo "GATE AUTHORSHIP: PASS -- $admitted_n admitted ($debt_n counted as manufacturing debt), $unmarked_n unmarked files under roots, 0 findings"
fi
